return ['domain'=>'hilo-chat','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es_ES','project-id-version'=>'Hilo Chat 1.0.0','pot-creation-date'=>'2026-11-20T04:19:17+01:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['Hilo Chat'=>'Hilo Chat','Live support chat for WooCommerce with an installable agent app (PWA), push notifications and customer context.'=>'Chat de soporte en vivo para WooCommerce con app de agentes instalable (PWA), notificaciones push y contexto del cliente.','Mauricio Correa'=>'Mauricio Correa','https://mauriciocorread.com/'=>'https://mauriciocorread.com/','Chats'=>'Chats','Settings'=>'Ajustes','Not allowed.'=>'No autorizado.','App icon'=>'Icono de la app','You have unsaved changes.'=>'Tienes cambios sin guardar.','Copied'=>'Copiado','%s team'=>'Equipo %s','Hidden'=>'Oculto','Test mode'=>'Modo prueba','Online now'=>'En línea ahora','Offline'=>'Desconectado','Live support for your store. Customers write from the chat widget and your team answers from the agent app, on desktop or phone.'=>'Soporte en vivo para tu tienda. Los clientes escriben desde el widget del chat y tu equipo responde desde la app de agentes, en el computador o el celular.','Open agent app'=>'Abrir app de agentes','Settings saved.'=>'Ajustes guardados.','Dismiss'=>'Descartar','%d resolved conversation deleted.'=>'Se eliminó %d conversación resuelta.' . "\0" . 'Se eliminaron %d conversaciones resueltas.','<strong>WhatsApp is on but the number is not valid,</strong> so it is not shown. Enter it with the country code.'=>'<strong>WhatsApp está activado pero el número no es válido,</strong> así que no se muestra. Escríbelo con el código de país.','Fix it'=>'Corregir','<strong>Test mode is on:</strong> only users who can answer chats see the widget. Turn it off to show it to every visitor.'=>'<strong>Modo prueba activo:</strong> solo los usuarios que pueden atender chats ven el widget. Desactívalo para mostrarlo a todos los visitantes.','Chat on the store'=>'Chat en la tienda','Choose who sees the chat button and where it sits.'=>'Elige quién ve el botón del chat y dónde aparece.','Show the chat on the store'=>'Mostrar el chat en la tienda','Turn it off to hide the chat button everywhere.'=>'Desactívalo para ocultar el botón del chat en todo el sitio.','Only agents see the widget, so you can try it before customers do.'=>'Solo los agentes ven el widget, así puedes probarlo antes que los clientes.','Hide on the checkout page'=>'Ocultar en la página de pago','Keeps the payment step free of distractions.'=>'Mantiene el paso de pago libre de distracciones.','Position'=>'Posición','Right'=>'Derecha','Bottom right corner'=>'Esquina inferior derecha','Left'=>'Izquierda','Bottom left corner'=>'Esquina inferior izquierda','WhatsApp'=>'WhatsApp','Customers choose between the live chat and WhatsApp from the same button.'=>'Los clientes eligen entre el chat en vivo y WhatsApp desde el mismo botón.','WhatsApp number'=>'Número de WhatsApp','Include the country code. Spaces, + and dashes are fine.'=>'Incluye el código de país. Puedes usar espacios, + y guiones.','Button text'=>'Texto del botón','Pre-filled message'=>'Mensaje predefinido','Use <code>{page}</code> for the page link and <code>{title}</code> for its title, so you know which product they are asking about.'=>'Usa <code>{page}</code> para el enlace de la página y <code>{title}</code> para su título, así sabrás por qué producto preguntan.','Texts'=>'Textos','Leave a field empty to use the default text, translated automatically into the store language.'=>'Deja un campo vacío para usar el texto por defecto, traducido automáticamente al idioma de la tienda.','Brand name'=>'Nombre de la marca','Team name'=>'Nombre del equipo','Widget title'=>'Título del widget','Greeting'=>'Saludo','first message customers see'=>'primer mensaje que ven los clientes','Online text'=>'Texto en línea','Offline text'=>'Texto fuera de línea','Greeting bubble'=>'Burbuja de saludo','Shown once per visit to people who have not opened the chat yet. It hides itself after 15 seconds; if the visitor closes it, it stays hidden for 3 days.'=>'Se muestra una vez por visita a quien todavía no ha abierto el chat. Se oculta sola a los 15 segundos; si el visitante la cierra, no vuelve a aparecer durante 3 días.','Bubble text'=>'Texto de la burbuja','Appears after'=>'Aparece a los','seconds'=>'segundos','Business hours'=>'Horario de atención','Site timezone: %s. Outside business hours, or when no agent is available, the widget invites visitors to leave a message and the reply arrives by email.'=>'Zona horaria del sitio: %s. Fuera de horario, o si no hay agentes disponibles, el widget invita a dejar un mensaje y la respuesta llega por email.','Open 24 hours, every day'=>'Atención 24 horas, todos los días','Ignores the weekly schedule below.'=>'Ignora el horario semanal de abajo.','24 h'=>'24 h','Opens at'=>'Abre a las','time rangeto'=>'a','Closes at'=>'Cierra a las','Closed'=>'Cerrado','Appearance'=>'Apariencia','Match the widget and the agent app to your brand. The preview updates as you edit.'=>'Adapta el widget y la app de agentes a tu marca. La vista previa se actualiza mientras editas.','Primary'=>'Principal','Header, button and team bubbles'=>'Cabecera, botón y burbujas del equipo','Accent'=>'Acento','Links and highlights'=>'Enlaces y destacados','Soft'=>'Suave','Backgrounds and customer bubbles'=>'Fondos y burbujas del cliente','Heading font'=>'Tipografía de títulos','Body font'=>'Tipografía de texto','Name of a font already loaded on the site, e.g. <code>"Tenor Sans", serif</code>. Use <code>inherit</code> to follow the theme.'=>'Nombre de una fuente ya cargada en el sitio, p. ej. <code>"Tenor Sans", serif</code>. Usa <code>inherit</code> para heredar la del tema.','Preview'=>'Vista previa','Do you ship to my city?'=>'¿Hacen envíos a mi ciudad?','See shipping options'=>'Ver opciones de envío','Chat'=>'Chat','Agent app icon'=>'Icono de la app de agentes','Choose image'=>'Elegir imagen','Use the default icon'=>'Usar el icono por defecto','Square 512×512 px PNG. Leave some space around the logo so Android does not crop it.'=>'PNG cuadrado de 512×512 px. Deja margen alrededor del logo para que Android no lo recorte.','Email logo (URL)'=>'Logo para emails (URL)','Shown on top of the primary color, so a light version works best. Many email clients do not display SVG: use PNG.'=>'Se muestra sobre el color principal, así que conviene una versión clara. Muchos clientes de correo no muestran SVG: usa PNG.','Advanced'=>'Avanzado','Technical options. The defaults work for most stores.'=>'Opciones técnicas. Los valores por defecto sirven para la mayoría de tiendas.','App path'=>'Ruta del panel','If you change it, agents will need to reinstall the app.'=>'Si la cambias, los agentes tendrán que reinstalar la app.','Push contact email (VAPID)'=>'Email de contacto push (VAPID)','Push services use it to contact you if there is a problem.'=>'Los servicios push lo usan para contactarte si hay algún problema.','Delete resolved chats after'=>'Borrar chats resueltos después de','days'=>'días','0 = keep them forever.'=>'0 = conservarlos siempre.','Save settings'=>'Guardar ajustes','Changes apply to the store as soon as you save.'=>'Los cambios se aplican en la tienda apenas guardas.','Agent app'=>'Panel de agentes','Answer chats from the browser or install it as an app on your phone or computer.'=>'Atiende los chats desde el navegador o instálalo como app en el celular o el computador.','Open app'=>'Abrir panel','Copy link'=>'Copiar enlace','Agents'=>'Agentes','Available'=>'Disponible','Away'=>'Ausente','To add agents, give them the <strong>Chat agent</strong> role in %s. Administrators and shop managers can answer chats too.'=>'Para sumar agentes, asígnales el rol <strong>Agente de chat</strong> en %s. Los administradores y gestores de tienda también pueden atender.','Users'=>'Usuarios','Resolved conversations'=>'Conversaciones resueltas','There is <strong>%d</strong> resolved conversation stored.'=>'Hay <strong>%d</strong> conversación resuelta guardada.' . "\0" . 'Hay <strong>%d</strong> conversaciones resueltas guardadas.','Delete all resolved conversations and their attachments? This cannot be undone.'=>'¿Eliminar todas las conversaciones resueltas y sus adjuntos? Esta acción no se puede deshacer.','Delete all resolved conversations now'=>'Eliminar ahora todas las conversaciones resueltas','%1$s · Made by %2$s'=>'%1$s · Hecho por %2$s','Answer %s chats'=>'Atiende los chats de %s','You are not allowed to answer chats. Ask an administrator for the "Chat agent" role.'=>'No tienes permiso para atender chats. Pide a un administrador el rol "Agente de chat".','Image'=>'Imagen','Visitor'=>'Visitante','quick reply shortcuthi'=>'hola','Hi! Thanks for writing to us. How can I help you?'=>'¡Hola! Gracias por escribirnos. ¿En qué te puedo ayudar?','quick reply shortcutshipping'=>'envio','Shipping times'=>'Tiempos de envío','Orders ship within 1 to 2 business days. As soon as yours ships, you will receive the tracking number by email.'=>'Los pedidos se despachan en 1 a 2 días hábiles. Apenas salga el tuyo, te llegará el número de guía por email.','quick reply shortcutthanks'=>'gracias','Goodbye'=>'Despedida','Thank you! If you need anything else, we are here. Have a lovely day 💛'=>'¡Gracias a ti! Si necesitas algo más, aquí estamos. Que tengas un lindo día 💛','%1$s replied to you at %2$s'=>'%1$s te respondió en %2$s','Sent an image'=>'Envió una imagen','New chat · %s'=>'Nuevo chat · %s','A chat was assigned to you'=>'Te asignaron un chat','%1$s transferred the conversation with %2$s to you.'=>'%1$s te transfirió la conversación con %2$s.','a visitor'=>'un visitante','Conversation not found.'=>'Conversación no encontrada.','The message is empty.'=>'El mensaje está vacío.','No file was received.'=>'No se recibió ningún archivo.','That user is not an agent.'=>'Ese usuario no es agente.','%s released the conversation.'=>'%s liberó la conversación.','%s joined the conversation.'=>'%s se unió a la conversación.','%1$s transferred the conversation to %2$s.'=>'%1$s transfirió la conversación a %2$s.','The conversation was marked as resolved.'=>'La conversación fue marcada como resuelta.','Only resolved conversations can be deleted.'=>'Solo se pueden eliminar conversaciones resueltas.','Only store managers can delete all resolved conversations.'=>'Solo los gestores de la tienda pueden eliminar todas las conversaciones resueltas.','Shortcut and text are required.'=>'El atajo y el texto son obligatorios.','This device could not be registered for notifications.'=>'No se pudo registrar este dispositivo para notificaciones.','Notifications are on ✅'=>'Notificaciones activas ✅','This is how we will let you know when a new message arrives.'=>'Así te avisaremos cuando llegue un mensaje nuevo.','Your message could not be sent.'=>'No se pudo enviar tu mensaje.','Please write your message.'=>'Escribe tu mensaje.','Please enter your name and a valid email so we can reply.'=>'Escribe tu nombre y un email válido para poder responderte.','The chat could not be started. Please try again.'=>'No se pudo iniciar el chat. Intenta de nuevo.','This conversation does not exist.'=>'La conversación no existe.','You are sending too many messages. Please wait a moment.'=>'Estás enviando demasiados mensajes. Espera un momento.','We will be back tomorrow.'=>'Volvemos mañana.','We will be back on %s.'=>'Volvemos el %s.','We will be back today at %s.'=>'Volvemos hoy a las %s.','We will be back tomorrow at %s.'=>'Volvemos mañana a las %s.','We will be back on %1$s at %2$s.'=>'Volvemos el %1$s a las %2$s.','Let\'s talk'=>'Hablemos','Hi! 👋 Do you have a question about a product or your order? Write to us.'=>'¡Hola! 👋 ¿Tienes alguna pregunta sobre un producto o tu pedido? Escríbenos.','Online · we reply in minutes'=>'En línea · respondemos en minutos','Leave us a message and we will reply by ema